SELECT 'item 68647 built (want 1)' AS what, COUNT(*) AS n FROM `item_template` WHERE `entry` = 68647
UNION ALL SELECT '  ...and its item_dbc row (want 1)', COUNT(*) FROM `item_dbc` WHERE `ID` = 68647
UNION ALL SELECT 'quests still sorted to a dead zone (want 0)', COUNT(*)
  FROM `quest_template` WHERE `QuestSortID` IN (4706, 5287)
UNION ALL SELECT '  ...moved to The Hinterlands (want 11)', COUNT(*)
  FROM `quest_template` WHERE `ID` IN (27290,27322,27333,27342,27349,27350,27364,27401,27405,27406,27423) AND `QuestSortID` = 47
UNION ALL SELECT '  ...moved to Durotar (want 1)', COUNT(*)
  FROM `quest_template` WHERE `ID` IN (28704) AND `QuestSortID` = 14
UNION ALL SELECT 'quests still rewarding a dead spell (want 0)', COUNT(*)
  FROM `quest_template` WHERE `RewardSpell` IN (89550,89669,89781,94710,95818)
UNION ALL SELECT 'chains still pointing at a missing quest (want 0)', COUNT(*)
  FROM `quest_template` q WHERE q.`RewardNextQuest` > 0
    AND NOT EXISTS (SELECT 1 FROM `quest_template` n WHERE n.`ID` = q.`RewardNextQuest`);

-- must be empty: a quest reward spell we kept that is in neither spell_dbc nor
-- the 10 that 88_ adds
SELECT 'PROBLEM: reward spell still missing' AS problem, `ID`, `RewardSpell`
FROM `quest_template` WHERE `RewardSpell` >= 70000
  AND NOT EXISTS (SELECT 1 FROM `spell_dbc` d WHERE d.`ID` = `RewardSpell`)
  AND `RewardSpell` NOT IN (83716,83865,83935,88763,88794,89457,90414,91768,92229,99387);

-- must be empty: item 68647 landed but with a display the client cannot draw
SELECT 'PROBLEM: 68647 display missing' AS problem, i.`entry`, i.`displayid`
FROM `item_template` i WHERE i.`entry` = 68647
  AND NOT EXISTS (SELECT 1 FROM `itemdisplayinfo_dbc` d WHERE d.`ID` = i.`displayid`);
